use galaga_reconstructed::{formation::stage_parameters, motion, Game, FIGHTER, ROCKET_0};

fn hash_objects(game: &Game) -> u64 {
    let mut hash = 14_695_981_039_346_656_037u64;
    for o in &game.objects {
        for b in [o.state as u8, o.code, o.colour, o.x, o.y as u8, (o.y >> 8) as u8 & 1, o.flags] {
            hash = (hash ^ b as u64).wrapping_mul(1_099_511_628_211);
        }
    }
    hash
}

#[test]
fn entrance_matches_reference_before_original_sortie_transition() {
    // Generated by compiling the pinned upstream C translation independently.
    // This is a whole-object-state comparison each frame, not a screenshot or
    // a golden generated by the Rust implementation. See evidence/README.md.
    let reference = include_bytes!("../evidence/reference-entrance.bin");
    let mut game = Game::default();
    let mut verified = 0;
    for (frame, expected) in reference.chunks_exact(8).take(896).enumerate() {
        game.step(0);
        if game.fault.is_some() { break; }
        assert_eq!(hash_objects(&game), u64::from_le_bytes(expected.try_into().unwrap()),
                   "object state differs from reference at frame {}", frame + 1);
        verified += 1;
    }
    assert!(verified > 800);
    assert_eq!(verified, 896);
    assert_eq!(game.fault, None);
    game.step(0);
    assert!(game.entrance_complete);
    assert_eq!(game.main_task_enable[8], 0);
    assert_eq!(game.main_task_enable[0x10], 1);
}

#[test]
fn first_stage_queue_preserves_original_order_and_markers() {
    let game = Game::default();
    assert_eq!(&game.wave_sequence[..9], &[0x7e, 0, 0x58, 0xc0, 0x28, 0, 0x5a, 0xc0, 0x2a]);
    assert_eq!(game.wave_sequence.iter().filter(|&&b| b == 0x7e).count(), 5);
    assert_eq!(game.wave_sequence[85], 0x7f);
    let mut ids: Vec<_> = (0..5).flat_map(|w| (0..8).map(move |i| game.wave_sequence[w * 17 + 2 + i * 2])).collect();
    ids.sort_unstable();
    ids.dedup();
    assert_eq!(ids.len(), 40);
}

#[test]
fn stage_parameters_follow_assembly_boundary_and_challenge_rule() {
    assert_eq!(&stage_parameters(1, 0)[..10], &[0, 0, 0, 0, 1, 2, 12, 6, 0, 0]);
    for rank in 0..4 {
        assert_eq!(stage_parameters(27, rank), stage_parameters(23, rank));
        assert_eq!(stage_parameters(28, rank), stage_parameters(24, rank));
        for stage in 1..=255 {
            let parameters = stage_parameters(stage, rank);
            assert_eq!(parameters[10], if stage < 3 || stage & 3 == 3 { 0 } else { 10 });
        }
    }
}

#[test]
fn fighter_keeps_original_alternating_steps_and_unclamped_limits() {
    let mut game = Game::default();
    let start = game.objects[FIGHTER].x;
    for expected_delta in [1, 3, 4, 6, 7, 9] {
        game.fighter_control(8); // right switch active low
        assert_eq!(game.objects[FIGHTER].x, start + expected_delta);
    }
    game.fighter_control(10); // neutral resets the step flag
    let x = game.objects[FIGHTER].x;
    game.fighter_control(2);
    assert_eq!(game.objects[FIGHTER].x, x - 1);
    game.objects[FIGHTER].x = 224;
    game.fighter_phase = 1;
    game.fighter_control(8);
    assert_eq!(game.objects[FIGHTER].x, 226); // original tests BEFORE adding
    game.fighter_control(8);
    assert_eq!(game.objects[FIGHTER].x, 226);
}

#[test]
fn rockets_keep_original_two_slots_step_and_screen_limits() {
    let mut game = Game::default();
    game.launch_rocket();
    game.launch_rocket();
    game.launch_rocket();
    assert_eq!(game.shots, 2);
    assert_eq!(game.rocket_attributes, [0xe0, 0xe0]);
    let y = game.objects[ROCKET_0].y;
    game.rocket_motion();
    assert_eq!(game.objects[ROCKET_0].y, y - 6);
    for _ in 0..50 { game.rocket_motion(); }
    assert_eq!(game.objects[ROCKET_0].x, 0);
    assert_eq!(game.objects[ROCKET_0 + 1].x, 0);
    game.launch_rocket();
    assert_eq!(game.shots, 3);
}

#[test]
fn integer_motion_keeps_wraparound_and_all_quadrants() {
    assert_eq!(motion::coordinate_step(65500, 1, 0, 3), (348, 1));
    assert_eq!(motion::coordinate_step(0, 0, 256, 3), (0, 384));
    assert_eq!(motion::coordinate_step(0, 0, 512, 3), (65152, 0));
    assert_eq!(motion::coordinate_step(0, 0, 768, 3), (0, 65152));
    assert_eq!(motion::divide(99, 0), 65535);
    assert_eq!(motion::divide(65535, 255), 257);
    assert_eq!(motion::flight_byte(0x0034), Err(0x0034)); // never interpret code as data
}

#[test]
fn arithmetic_matches_independent_reference_exhaustively() {
    let expected = include_bytes!("../evidence/reference-arithmetic.bin");
    fn add(hash: &mut u64, word: u16) {
        for b in word.to_le_bytes() { *hash = (*hash ^ b as u64).wrapping_mul(1_099_511_628_211); }
    }
    let initial = 14_695_981_039_346_656_037u64;
    let mut hashes = [initial; 3];
    // Every u16 numerator and every u8 denominator, including zero.
    for d in 0..=255 {
        for n in 0..=65535 { add(&mut hashes[0], motion::divide(n, d)); }
    }
    // All 65,536 position pairs against a target that exercises every octant.
    for x in 0..=255 {
        for y in 0..=255 { add(&mut hashes[1], motion::home_angle(x, y, 0x80, 0x40)); }
    }
    // Every angle, every displacement nibble, and four wraparound seeds.
    for angle in 0..1024 {
        for ds in 0..16 {
            for seed in 0..4 {
                let (x, y) = motion::coordinate_step(seed * 21845, 65535 - seed * 21845, angle, ds);
                add(&mut hashes[2], x);
                add(&mut hashes[2], y);
            }
        }
    }
    for (i, bytes) in expected.chunks_exact(8).enumerate() {
        assert_eq!(hashes[i], u64::from_le_bytes(bytes.try_into().unwrap()), "arithmetic group {i}");
    }
}
